2758	 *  stmmac_open - open entry point of the driver
2759	 *  @dev : pointer to the device structure.
2760	 *  Description:
2761	 *  This function is the open entry point of the driver.
2762	 *  Return value:
2763	 *  0 on success and an appropriate (-)ve integer as defined in errno.h
2764	 *  file on failure.
2765	 */
2766	static int stmmac_open(struct net_device *dev)
2767	{
2768		struct stmmac_priv *priv = netdev_priv(dev);
2769		int bfsize = 0;
2770		u32 chan;
2771		int ret;
2772	
2773		if (priv->hw->pcs != STMMAC_PCS_TBI &&
2774		    priv->hw->pcs != STMMAC_PCS_RTBI &&
2775		    priv->hw->xpcs == NULL) {
2776			ret = stmmac_init_phy(dev);
2777			if (ret) {
2778				netdev_err(priv->dev,
2779					   "%s: Cannot attach to PHY (error: %d)\n",
2780					   __func__, ret);
2781				return ret;
2782			}
2783		}
2784	
2785		/* Extra statistics */
2786		memset(&priv->xstats, 0, sizeof(struct stmmac_extra_stats));
2787		priv->xstats.threshold = tc;
2788	
2789		bfsize = stmmac_set_16kib_bfsize(priv, dev->mtu);
2790		if (bfsize < 0)
2791			bfsize = 0;
2792	
2793		if (bfsize < BUF_SIZE_16KiB)
2794			bfsize = stmmac_set_bfsize(dev->mtu, priv->dma_buf_sz);
2795	
2796		priv->dma_buf_sz = bfsize;
2797		buf_sz = bfsize;
2798	
2799		priv->rx_copybreak = STMMAC_RX_COPYBREAK;
2800	
2801		if (!priv->dma_tx_size)
2802			priv->dma_tx_size = DMA_DEFAULT_TX_SIZE;
2803		if (!priv->dma_rx_size)
2804			priv->dma_rx_size = DMA_DEFAULT_RX_SIZE;
2805	
2806		/* Earlier check for TBS */
2807		for (chan = 0; chan < priv->plat->tx_queues_to_use; chan++) {
2808			struct stmmac_tx_queue *tx_q = &priv->tx_queue[chan];
2809			int tbs_en = priv->plat->tx_queues_cfg[chan].tbs_en;
2810	
2811			tx_q->tbs |= tbs_en ? STMMAC_TBS_AVAIL : 0;
2812			if (stmmac_enable_tbs(priv, priv->ioaddr, tbs_en, chan))
2813				tx_q->tbs &= ~STMMAC_TBS_AVAIL;
2814		}
2815	
2816		ret = alloc_dma_desc_resources(priv);
2817		if (ret < 0) {
2818			netdev_err(priv->dev, "%s: DMA descriptors allocation failed\n",
2819				   __func__);
2820			goto dma_desc_error;
2821		}
2822	
2823		ret = init_dma_desc_rings(dev, GFP_KERNEL);
2824		if (ret < 0) {
2825			netdev_err(priv->dev, "%s: DMA descriptors initialization failed\n",
2826				   __func__);
2827			goto init_error;
2828		}
2829	
