3572	 * @priv: driver private structure
3573	 * @queue: RX queue index
3574	 * Description : this is to reallocate the skb for the reception process
3575	 * that is based on zero-copy.
3576	 */
3577	static inline void stmmac_rx_refill(struct stmmac_priv *priv, u32 queue)
3578	{
3579		struct stmmac_rx_queue *rx_q = &priv->rx_queue[queue];
3580		int len, dirty = stmmac_rx_dirty(priv, queue);
3581		unsigned int entry = rx_q->dirty_rx;
3582	
3583		len = DIV_ROUND_UP(priv->dma_buf_sz, PAGE_SIZE) * PAGE_SIZE;
3584	
3585		while (dirty-- > 0) {
3586			struct stmmac_rx_buffer *buf = &rx_q->buf_pool[entry];
3587			struct dma_desc *p;
3588			bool use_rx_wd;
3589	
3590			if (priv->extend_desc)
3591				p = (struct dma_desc *)(rx_q->dma_erx + entry);
3592			else
3593				p = rx_q->dma_rx + entry;
3594	
3595			if (!buf->page) {
3596				buf->page = page_pool_dev_alloc_pages(rx_q->page_pool);
3597				if (!buf->page)
3598					break;
3599			}
3600	
3601			if (priv->sph && !buf->sec_page) {
3602				buf->sec_page = page_pool_dev_alloc_pages(rx_q->page_pool);
3603				if (!buf->sec_page)
3604					break;
3605	
3606				buf->sec_addr = page_pool_get_dma_addr(buf->sec_page);
3607	
3608				dma_sync_single_for_device(priv->device, buf->sec_addr,
3609							   len, DMA_FROM_DEVICE);
3610			}
3611	
3612			buf->addr = page_pool_get_dma_addr(buf->page);
3613	
3614			/* Sync whole allocation to device. This will invalidate old
3615			 * data.
3616			 */
3617			dma_sync_single_for_device(priv->device, buf->addr, len,
3618						   DMA_FROM_DEVICE);
3619	
3620			stmmac_set_desc_addr(priv, p, buf->addr);
3621			stmmac_set_desc_sec_addr(priv, p, buf->sec_addr);
3622			stmmac_refill_desc3(priv, rx_q, p);
3623	
3624			rx_q->rx_count_frames++;
3625			rx_q->rx_count_frames += priv->rx_coal_frames;
3626			if (rx_q->rx_count_frames > priv->rx_coal_frames)
3627				rx_q->rx_count_frames = 0;
3628	
3629			use_rx_wd = !priv->rx_coal_frames;
3630			use_rx_wd |= rx_q->rx_count_frames > 0;
3631			if (!priv->use_riwt)
3632				use_rx_wd = false;
3633	
3634			dma_wmb();
3635			stmmac_set_rx_owner(priv, p, use_rx_wd);
3636	
3637			entry = STMMAC_GET_ENTRY(entry, priv->dma_rx_size);
3638		}
3639		rx_q->dirty_rx = entry;
3640		rx_q->rx_tail_addr = rx_q->dma_rx_phy +
3641				    (rx_q->dirty_rx * sizeof(struct dma_desc));
3642		stmmac_set_rx_tail_ptr(priv, priv->ioaddr, rx_q->rx_tail_addr, queue);
3643	}
