2653			    (speed == SPEED_1000)) {
2654				priv->hw->ps = speed;
2655			} else {
2656				dev_warn(priv->device, "invalid port speed\n");
2657				priv->hw->ps = 0;
2658			}
2659		}
2660	
2661		/* Initialize the MAC Core */
2662		stmmac_core_init(priv, priv->hw, dev);
