2669	
2670		ret = stmmac_rx_ipc(priv, priv->hw);
2671		if (!ret) {
2672			netdev_warn(priv->dev, "RX IPC Checksum Offload disabled\n");
2673			priv->plat->rx_coe = STMMAC_RX_COE_NONE;
2674			priv->hw->rx_csum = 0;
2675		}
