3928	static int stmmac_napi_poll_tx(struct napi_struct *napi, int budget)
3929	{
3930		struct stmmac_channel *ch =
3931			container_of(napi, struct stmmac_channel, tx_napi);
3932		struct stmmac_priv *priv = ch->priv_data;
3933		u32 chan = ch->index;
3934		int work_done;
3935	
3936		priv->xstats.napi_poll++;
3937	
3938		work_done = stmmac_tx_clean(priv, priv->dma_tx_size, chan);
3939		work_done = min(work_done, budget);
3940	
3941		if (work_done < budget && napi_complete_done(napi, work_done)) {
3942			unsigned long flags;
3943	
3944			spin_lock_irqsave(&ch->lock, flags);
3945			stmmac_enable_dma_irq(priv, priv->ioaddr, chan, 0, 1);
3946			spin_unlock_irqrestore(&ch->lock, flags);
3947		}
3948	
3949		return work_done;

