## 四、U-Boot 中的完整初始化流程

```c
// 1. DMA 软复位
writel(DMAMAC_SRST, &dma_p->busmode);           // 0x1000 bit0=1
while (readl(&dma_p->busmode) & DMAMAC_SRST);   // 等待复位完成

// 2. 写 MAC 地址
writel(macid_hi, &mac_p->macaddr0hi);           // 0x0040
writel(macid_lo, &mac_p->macaddr0lo);           // 0x0044

// 3. 初始化 RX 描述符环
for (idx = 0; idx < 16; idx++) {
    desc_p[idx].dmamac_addr = &rxbuffs[idx * 2048];  // buffer 地址
    desc_p[idx].dmamac_next = &desc_p[idx + 1];      // 链表指针
    desc_p[idx].dmamac_cntl = 1600 | DESC_RXCTRL_RXCHAIN;  // 长度+chain
    desc_p[idx].txrx_status = DESC_RXSTS_OWNBYDMA;   // OWN=1
}
desc_p[15].dmamac_next = &desc_p[0];  // 环形：最后一个指向第一个

// 4. 写 RX 描述符基地址到 DMA
writel(&desc_table_p[0], &dma_p->rxdesclistaddr);  // ★0x100C

// 5. 配置 DMA
writel(FIXEDBURST | DMA_PBL, &dma_p->busmode);     // 0x1000
writel(STOREFORWARD, &dma_p->opmode);               // 0x1018

// 6. 启动 DMA RX/TX
writel(RXSTART | TXSTART, &dma_p->opmode);          // 0x1018 bit1+bit13

// 7. 使能 MAC 收发
writel(RXENABLE | TXENABLE, &mac_p->conf);          // 0x0000 bit2+bit3
```

