882	/****************************************************************************
883	 * Private Functions — MAC Address Configuration
884	 *
885	 * Reference: Manual §4.4 Step 6, §10.3 Phase 5.3
886	 ****************************************************************************/
887	
888	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
889	{
890	  uint32_t hi;
891	  uint32_t lo;
892	
893	  hi = ((uint32_t)mac[5] << 8) | (uint32_t)mac[4] | GMAC_HI_REG_AE;
894	  lo = ((uint32_t)mac[3] << 24) | ((uint32_t)mac[2] << 16) |
895	       ((uint32_t)mac[1] << 8)  | (uint32_t)mac[0];
896	
897	  putreg32(hi, gmac_base + GMAC_MAC_ADDR0_HIGH);
898	  putreg32(lo, gmac_base + GMAC_MAC_ADDR0_LOW);
899	
900	  ethinfo("MAC addr set: %02x:%02x:%02x:%02x:%02x:%02x\n",
901	          mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
902	}
903	
904	/****************************************************************************
905	 * Private Functions — MAC Core and DMA Initialization
906	 *
907	 * Performs the full hardware initialization sequence:
908	 *   - DMA bus mode and AXI configuration
909	 *   - MAC core init (GMAC_CONTROL, interrupt mask, frame filter)
910	 *   - DMA operation mode (Store-and-Forward)
911	 *   - Interrupt enable
912	 *   - Write descriptor base addresses
913	 *   - Start DMA TX and RX
914	 *
915	 * Reference: Manual §10.3 Phase 2, 5, 6, 7
916	 ****************************************************************************/
917	
918	static int hw_setup(struct sg2000_eth_priv_s *priv)
919	{
920	  uintptr_t gmac_base = priv->gmac_base;
921	  uint32_t val;
922	
923	  /* --- Phase 2: DMA software reset --- */
924	
925	  if (dma_soft_reset(gmac_base) < 0)
926	    {
927	      return -ETIMEDOUT;
928	    }
929	
930	  /* --- Phase 2.2: Configure DMA Bus Mode ---
931	   * PBL=8, RPBL=8, FB=1 (fixed burst), USP=1 (separate PBL),
932	   * AAL=1 (address-aligned beats).  ATDS is NOT set (basic descriptors).
933	   * Use explicit constants; (DMA_PBL_8 & 0x3f) would be 0 (PBL field is
934	   * at bits 8-13, masking with 0x3f gives 0).
935	   */
936	
937	  val = DMA_PBL_8 | ((3 << DMA_RPBL_SHIFT) & DMA_RPBL_MASK) |
938	        DMA_FB | DMA_USP | DMA_AAL;
939	  putreg32(val, gmac_base + DMA_BUS_MODE);
940	
941	  /* --- Phase 2.3: Configure AXI bus ---
942	   * WR_OSR_LMT=1, RD_OSR_LMT=2, BLEN support for 4/8/16 beats.
943	   */
944	
945	  putreg32((1 << DMA_AXI_WR_OSR_LMT_SHIFT) |
946	           (2 << DMA_AXI_RD_OSR_LMT_SHIFT) |
947	           (0xf << DMA_AXI_BLEN_SHIFT),
948	           gmac_base + DMA_AXI_BUS_MODE);
949	
950	  ethinfo("DMA: bus_mode=0x%08" PRIX32 " axi=0x%08" PRIX32 "\n",
951	          getreg32(gmac_base + DMA_BUS_MODE),
952	          getreg32(gmac_base + DMA_AXI_BUS_MODE));
953	
954	  /* --- Phase 5.1: Configure GMAC_CONTROL ---
955	   * Use read-modify-write to preserve speed/duplex (FES, DM) already
956	   * set by gmac_set_speed_duplex() before hw_setup() was called.
957	   */
958	
959	  val = getreg32(gmac_base + GMAC_CONTROL);
960	  putreg32(val | GMAC_CORE_INIT, gmac_base + GMAC_CONTROL);
961	
962	  /* --- Phase 5.2: Configure GMAC_INT_MASK (disable all MAC interrupts,
963	   *   use DMA interrupts only) ---
964	   */
965	
966	  putreg32(GMAC_INT_DEFAULT_MASK, gmac_base + GMAC_INT_MASK);
967	
968	  /* --- Phase 5.4: Configure frame filter ---
969	   * Use promiscuous mode (PR) to accept all packets.  This matches the
970	   * old driver's setup and avoids MAC address filtering issues.
971	   */
972	
973	  putreg32(GMAC_FILTER_PR | GMAC_FILTER_HMC | GMAC_FILTER_PM,
974	           gmac_base + GMAC_FRAME_FILTER);
975	
976	  /* Clear VLAN tag */
977	
978	  putreg32(0, gmac_base + GMAC_VLAN_TAG);
979	
980	  /* Clear pending MAC and DMA interrupts */
981	
982	  putreg32(0xffffffff, gmac_base + GMAC_INT_STATUS);
983	  putreg32(DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
984	
985	  /* --- Phase 5.5: Enable MAC TX and RX --- */
986	
987	  val = getreg32(gmac_base + GMAC_CONTROL);
988	  putreg32(val | GMAC_CONTROL_TE | GMAC_CONTROL_RE, gmac_base + GMAC_CONTROL);
989	
990	  /* --- Phase 6.1: Configure DMA operation mode ---
991	   * RSF=1 (RX Store-and-Forward), TSF=1 (TX Store-and-Forward),
992	   * OSF=1 (Operate on Second Frame), RTC=64, TTC=64.
993	   */
994	
995	  val = getreg32(gmac_base + DMA_CONTROL);
996	  val |= DMA_CONTROL_RSF | DMA_CONTROL_TSF | DMA_CONTROL_OSF |
997	         DMA_CONTROL_RTC_64 | DMA_CONTROL_TTC_64;
998	  putreg32(val, gmac_base + DMA_CONTROL);
999	
1000	  /* --- Phase 6.2: Enable DMA interrupts --- */
1001	
1002	  putreg32(DMA_INTR_DEFAULT_MASK, gmac_base + DMA_INTR_ENA);
1003	
1004	  /* --- Phase 7.1: Write descriptor base addresses --- */
1005	
1006	  putreg32(priv->tx_desc_phys, gmac_base + DMA_TX_BASE_ADDR);
1007	  putreg32(priv->rx_desc_phys, gmac_base + DMA_RCV_BASE_ADDR);
1008	
1009	  /* --- Phase 7.2-7.3: Start DMA TX and RX ---
1010	   * Write ST first, then SR separately with a delay.  The hardware
1011	   * may ignore SR if written simultaneously with ST.
1012	   */
1013	
1014	  val = getreg32(gmac_base + DMA_CONTROL);
1015	  putreg32(val | DMA_CONTROL_ST, gmac_base + DMA_CONTROL);
1016	  up_udelay(10);
1017	
1018	  val = getreg32(gmac_base + DMA_CONTROL);
1019	  putreg32(val | DMA_CONTROL_SR, gmac_base + DMA_CONTROL);
1020	  up_udelay(10);
1021	
1022	  ethinfo("MAC/DMA started: gmac_ctrl=0x%08" PRIX32
1023	          " dma_ctrl=0x%08" PRIX32 " dma_status=0x%08" PRIX32
1024	          " dma_intr=0x%08" PRIX32 "\n",
1025	          getreg32(gmac_base + GMAC_CONTROL),
1026	          getreg32(gmac_base + DMA_CONTROL),
1027	          getreg32(gmac_base + DMA_STATUS),
1028	          getreg32(gmac_base + DMA_INTR_ENA));
1029	
1030	  return OK;
1031	}
