1327	/****************************************************************************
1328	 * Name: netdriver_ifup
1329	 *
1330	 * Description:
1331	 *   OpenVela netdev_ops_s ifup callback.  Performs the full hardware
1332	 *   initialization sequence and brings the interface online.
1333	 *
1334	 * Reference: Manual §4.3, §10.3, §10.11
1335	 ****************************************************************************/
1336	
1337	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1338	{
1339	  FAR struct sg2000_eth_priv_s *priv =
1340	      (FAR struct sg2000_eth_priv_s *)dev;
1341	  int ret;
1342	
1343	  ethinfo("ifup begin\n");
1344	
1345	  /* 1. Enable clocks and deassert resets */
1346	
1347	  gmac_clock_enable();
1348	
1349	  /* 2. Set GMAC_CORE_INIT (includes PS=MII mode) before PHY operations */
1350	
1351	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONTROL);
1352	
1353	  /* 3. Initialize EPHY via APB */
1354	
1355	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1356	
1357	  /* 4. Verify MDIO communication with PHY */
1358	
1359	  ret = mdio_verify_phy(priv->gmac_base);
1360	  if (ret < 0)
1361	    {
1362	      etherr("PHY not responding: %d\n", ret);
1363	      return ret;
1364	    }
1365	
1366	  ethinfo("MDIO operational, mdio_addr=0x%08" PRIX32
1367	          " mdio_data=0x%08" PRIX32 "\n",
1368	          getreg32(priv->gmac_base + GMAC_MII_ADDR),
1369	          getreg32(priv->gmac_base + GMAC_MII_DATA));
1370	
1371	  /* 5. Run EPHY full analog tuning (requires operational MDIO) */
1372	
1373	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1374	
1375	  /* 6. Allocate DMA resources (once) */
1376	
1377	  ret = alloc_dma(priv);
1378	  if (ret < 0)
1379	    {
1380	      etherr("alloc_dma failed: %d\n", ret);
1381	      return ret;
1382	    }
1383	
1384	  /* 7. Initialize descriptor rings */
1385	
1386	  init_desc_rings(priv);
1387	
1388	  /* 8. Set MAC address */
1389	
1390	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1391	
1392	  /* 9. Configure PHY (auto-negotiation) BEFORE starting DMA.
1393	   *    Starting DMA while the PHY is in reset causes the TX path to
1394	   *    stall (frames held in FIFO with no RMII link) and the RX path
1395	   *    to pick up garbage from an unstable RMII interface.
1396	   */
1397	
1398	  ret = phy_config_init(priv);
1399	  if (ret < 0)
1400	    {
1401	      etherr("PHY config failed: %d\n", ret);
1402	      return ret;
1403	    }
1404	
1405	  /* Apply negotiated speed/duplex to GMAC before DMA start */
1406	
1407	  gmac_set_speed_duplex(priv->gmac_base, priv->speed, priv->duplex);
1408	
1409	  /* 10. Hardware setup: DMA reset, MAC core, DMA mode, start DMA.
1410	   *    Performed AFTER PHY is ready — clean RMII link and stable speed.
1411	   */
1412	
1413	  ret = hw_setup(priv);
1414	  if (ret < 0)
1415	    {
1416	      etherr("hw_setup failed: %d\n", ret);
1417	      return ret;
1418	    }
1419	
1420	  /* 11. Ring RX doorbell and enable interrupts (last, after all HW init) */
1421	
1422	  rx_doorbell(priv->gmac_base);
1423	  up_enable_irq(priv->irq);
1424	
1425	  /* 12. Signal carrier on to the network stack (if link detected) */
1426	
1427	  if (priv->link_up)
1428	    {
1429	      netdev_lower_carrier_on(dev);
1430	    }
1431	
1432	  ethinfo("ifup done: %d Mbps %s duplex, link=%s\n",
1433	          priv->speed, priv->duplex ? "Full" : "Half",
1434	          priv->link_up ? "up" : "down");
1435	
1436	  return OK;
1437	}
1438	
1439	/****************************************************************************
1440	 * Name: netdriver_ifdown
1441	 *
1442	 * Description:
1443	 *   OpenVela netdev_ops_s ifdown callback.  Stops DMA, disables MAC,
1444	 *   and disables interrupts.
1445	 *
1446	 * Reference: Manual §4.3
1447	 ****************************************************************************/
1448	
1449	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1450	{
1451	  FAR struct sg2000_eth_priv_s *priv =
1452	      (FAR struct sg2000_eth_priv_s *)dev;
1453	  uintptr_t gmac_base = priv->gmac_base;
1454	  uint32_t val;
1455	
1456	  up_disable_irq(priv->irq);
1457	
1458	  /* Stop TX and RX DMA */
1459	
1460	  val = getreg32(gmac_base + DMA_CONTROL);
1461	  putreg32(val & ~(DMA_CONTROL_ST | DMA_CONTROL_SR), gmac_base + DMA_CONTROL);
1462	
1463	  /* Disable MAC TX/RX */
1464	
1465	  val = getreg32(gmac_base + GMAC_CONTROL);
1466	  putreg32(val & ~(GMAC_CONTROL_TE | GMAC_CONTROL_RE),
1467	           gmac_base + GMAC_CONTROL);
1468	
1469	  /* Disable DMA interrupts */
1470	
1471	  putreg32(0, gmac_base + DMA_INTR_ENA);
1472	
1473	  /* Clear pending interrupts */
1474	
1475	  putreg32(DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
1476	
1477	  netdev_lower_carrier_off(dev);
1478	
1479	  priv->link_up = 0;
1480	
1481	  ethinfo("ifdown: interface stopped\n");
1482	
1483	  return OK;
1484	}
1485	
1486	/****************************************************************************
1487	 * Name: netdriver_transmit
1488	 *
1489	 * Description:
1490	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet via DMA.
1491	 *   The driver takes ownership of the netpkt and MUST free it after
1492	 *   TX completion (in tx_cleanup) or on error.
1493	 *
1494	 * Reference: Manual §5.1, §10.4
1495	 ****************************************************************************/
1496	
1497	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1498	                               FAR netpkt_t *pkt)
1499	{
1500	  FAR struct sg2000_eth_priv_s *priv =
1501	      (FAR struct sg2000_eth_priv_s *)dev;
1502	  unsigned int len = netpkt_getdatalen(dev, pkt);
1503	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1504	  const uint8_t *data;
1505	  irqstate_t flags;
1506	  int ret;
1507	
1508	  if (len > SG2000_ETH_BUFSIZE)
1509	    {
1510	      etherr("TX packet too large: %u\n", len);
1511	      return -E2BIG;
1512	    }
1513	
1514	  /* Extract data from netpkt.  If fragmented, copy to tmp_buf;
1515	   * otherwise use pointer directly.
1516	   */
1517	
1518	  if (netpkt_is_fragmented(pkt))
1519	    {
1520	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1521	      data = tmp_buf;
1522	    }
1523	  else
1524	    {
1525	      data = netpkt_getdata(dev, pkt);
1526	      if (!data)
1527	        {
1528	          etherr("netpkt_getdata returned NULL\n");
1529	          return -EINVAL;
1530	        }
1531	    }
1532	
1533	  /* Transmit via DMA.  Track the netpkt BEFORE calling hw_transmit
1534	   * (which advances tx_cur) so the ISR can't observe a half-committed
1535	   * slot.  The whole section runs with IRQs off to close the race
1536	   * between pkt store, cur advance, and ISR tx_cleanup.
1537	   *
1538	   * On failure, do NOT free the netpkt — the upper half recycles it.
1539	   */
1540	
1541	  flags = up_irq_save();
1542	  priv->tx_pkt[priv->tx_cur] = pkt;
1543	
1544	  ret = hw_transmit(priv, data, len);
1545	  if (ret < 0)
1546	    {
1547	      priv->tx_pkt[priv->tx_cur] = NULL;  /* Undo — slot not consumed */
1548	      up_irq_restore(flags);
1549	      etherr("hw_transmit failed: %d\n", ret);
1550	      return ret;
1551	    }
1552	
1553	  up_irq_restore(flags);
1554	
1555	  return OK;
1556	}
1557	
1558	/****************************************************************************
1559	 * Name: netdriver_receive
1560	 *
1561	 * Description:
1562	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1563	 *   netdev_lower_rxready() was signaled.  Returns one received packet,
1564	 *   or NULL if no more packets are available.
1565	 *
1566	 * Reference: Manual §6, §10.5
1567	 ****************************************************************************/
1568	
1569	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1570	{
1571	  FAR struct sg2000_eth_priv_s *priv =
1572	      (FAR struct sg2000_eth_priv_s *)dev;
1573	  FAR netpkt_t *pkt = NULL;
1574	  struct sg2000_dma_desc_s *desc;
1575	  uintptr_t gmac_base = priv->gmac_base;
1576	  uint32_t status;
1577	  int frame_len;
1578	  int ret;
1579	
1580	  desc = &priv->rx_desc[priv->rx_cur];
1581	
1582	  /* Invalidate descriptor cache line to read DMA-written status */
1583	
1584	  dcache_invalidate_range((uintptr_t)desc,
1585	                          (uintptr_t)desc +
1586	                          sizeof(struct sg2000_dma_desc_s));
1587	
1588	  /* Check if DMA still owns the descriptor (no packet ready) */
1589	
1590	  if (desc->des0 & RDES0_OWN)
1591	    {
1592	      return NULL;
1593	    }
1594	
1595	  status = desc->des0;
1596	
1597	  /* Check for receive errors */
1598	
1599	  if (status & RDES0_ERROR_SUMMARY)
1600	    {
1601	      etherr("RX error status=0x%08" PRIX32 "\n", status);
1602	      goto refill;
1603	    }
1604	
1605	  /* Verify we got a complete frame (first AND last descriptor) */
1606	
1607	  if (!(status & RDES0_FIRST_DESCRIPTOR) ||
1608	      !(status & RDES0_LAST_DESCRIPTOR))
1609	    {
1610	      ethwarn("RX incomplete frame, status=0x%08" PRIX32 "\n", status);
1611	      goto refill;
1612	    }
1613	
1614	  /* Get frame length (includes 4-byte FCS which we strip) */
1615	
1616	  frame_len = (int)((status & RDES0_FRAME_LEN_MASK) >> RDES0_FRAME_LEN_SHIFT)
1617	              - ETH_FCSSLEN;
1618	
1619	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1620	    {
1621	      ethwarn("RX invalid frame length: %d\n", frame_len);
1622	      goto refill;
1623	    }
1624	
1625	  /* Invalidate RX data buffer to read DMA-written data */
1626	
1627	  dcache_invalidate_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1628	                          (uintptr_t)priv->rx_buf[priv->rx_cur] +
1629	                          RX_BUF_SIZE);
1630	
1631	  /* Allocate a netpkt for the received data */
1632	
1633	  pkt = netpkt_alloc(dev, NETPKT_RX);
1634	  if (!pkt)
1635	    {
1636	      etherr("netpkt_alloc failed\n");
1637	      goto refill;
1638	    }
1639	
1640	  /* Copy data from DMA buffer into netpkt */
1641	
1642	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1643	  if (ret < 0)
1644	    {
1645	      etherr("netpkt_copyin failed: %d\n", ret);
1646	      netpkt_free(dev, pkt, NETPKT_RX);
1647	      pkt = NULL;
1648	      goto refill;
1649	    }
1650	
1651	  ethinfo("RX: %d bytes desc[%u]\n", frame_len, priv->rx_cur);
1652	
1653	refill:
1654	  /* Return descriptor to DMA: set OWN=1, restore buffer address.
1655	   * Preserve END_RING bit for the last descriptor in des1.
1656	   */
1657	
1658	  desc->des0 = RDES0_OWN;
1659	  desc->des1 = (RX_BUF_SIZE & RDES1_BUFFER1_SIZE_MASK) |
1660	               ((priv->rx_cur == (RX_RING_SIZE - 1)) ? RDES1_END_RING : 0);
1661	  desc->des2 = priv->rx_buf_phys[priv->rx_cur];
1662	
1663	  /* Flush RX buffer before handing it back to DMA */
1664	
1665	  dcache_flush_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1666	                     (uintptr_t)priv->rx_buf[priv->rx_cur] + RX_BUF_SIZE);
1667	
1668	  /* Write back descriptor so DMA sees OWN=1 */
1669	
1670	  dcache_clean_range((uintptr_t)desc,
1671	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1672	
1673	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1674	  rx_doorbell(gmac_base);
1675	
1676	  return pkt;
1677	}
