1682	
1683	static const struct netdev_ops_s g_ops =
1684	{
1685	  netdriver_ifup,      /* ifup */
1686	  netdriver_ifdown,    /* ifdown */
1687	  netdriver_transmit,  /* transmit */
1688	  netdriver_receive    /* receive */
