1692	 * Public Functions
1693	 ****************************************************************************/
1694	
1695	/****************************************************************************
1696	 * Name: sg2000_eth_initialize
1697	 *
1698	 * Description:
1699	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1700	 *   network stack as a netdev_lowerhalf_s device.
1701	 *
1702	 *   Called from board_late_initialize() during system bringup.
1703	 *
1704	 ****************************************************************************/
1705	
1706	int sg2000_eth_initialize(void)
1707	{
1708	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1709	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1710	  int ret;
1711	
1712	  if (g_eth_initialized)
1713	    {
1714	      return OK;
1715	    }
1716	
1717	  /* Initialize private data */
1718	
1719	  memset(priv, 0, sizeof(*priv));
1720	  priv->gmac_base = SG2000_GMAC_BASE;
1721	  priv->phy_base  = SG2000_EPHY_BASE;
1722	  priv->phy_top   = SG2000_EPHY_TOP;
1723	
1724	  /* Set default MAC address (should be replaced with eFuse/OTP value) */
1725	
1726	  priv->mac_addr[0] = 0x02;
1727	  priv->mac_addr[1] = 0x00;
1728	  priv->mac_addr[2] = 0x00;
1729	  priv->mac_addr[3] = 0x00;
1730	  priv->mac_addr[4] = 0x00;
1731	  priv->mac_addr[5] = 0x01;
1732	
1733	  /* Copy MAC address to the netdev structure */
1734	
1735	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1736	         IFHWADDRLEN);
1737	
1738	  /* Configure device quotas and operations.
1739	   * Total quota (TX + RX) must not exceed CONFIG_IOB_NBUFFERS.
1740	   * With CONFIG_IOB_NBUFFERS=64, we reserve 16 each (32 total).
1741	   */
1742	
1743	  dev->quota[NETPKT_TX] = 16;
1744	  dev->quota[NETPKT_RX] = 16;
1745	  dev->ops              = &g_ops;
1746	
1747	  /* Get the GMAC interrupt number */
1748	
1749	  priv->irq = SG2000_IRQ_GMAC;
1750	
1751	  /* Register with the OpenVela network stack */
1752	
1753	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1754	  if (ret < 0)
1755	    {
1756	      etherr("netdev_lower_register failed: %d\n", ret);
1757	      return ret;
1758	    }
1759	
1760	  /* Initially, carrier is off */
1761	
1762	  netdev_lower_carrier_off(dev);
1763	  g_eth_initialized = true;
1764	
1765	  ethinfo("SG2000 Ethernet driver registered as eth0\n");
1766	
1767	  /* Attach interrupt handler (once).
1768	   * The IRQ is NOT enabled here — it is enabled at the end of
1769	   * netdriver_ifup() only after the hardware is fully configured.
1770	   */
1771	
1772	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1773	  if (ret < 0)
1774	    {
1775	      etherr("irq_attach failed: %d\n", ret);
1776	      return OK;  /* Driver is still registered, just no interrupts */
1777	    }
1778	
1779	  ethinfo("IRQ %d attached (not yet enabled)\n", priv->irq);
1780	
1781	  return OK;
1782	}
